import sqlite3
import pandas as pd
import pyarrow.parquet as pq
from pathlib import Path

# backend/database/
HERE = Path(__file__).resolve().parent
PROJECT_ROOT = HERE.parent.parent     # urban-mobility-data-explorer/

SCHEMA_PATH = HERE / "schema.sql"
DB_PATH = HERE / "urban_mobility.db"
OUTPUT_DIR = PROJECT_ROOT / "data" / "output"

# Column order must match the INSERT statement (trip_id is generated by the DB)
TRIP_COLUMNS = [
    "vendor_id",
    "pickup_datetime",
    "dropoff_datetime",
    "passenger_count",
    "trip_distance",
    "rate_code_id",
    "store_and_fwd_flag",
    "pu_location_id",
    "do_location_id",
    "payment_type_id",
    "fare_amount",
    "extra",
    "mta_tax",
    "tip_amount",
    "tolls_amount",
    "improvement_surcharge",
    "total_amount",
    "congestion_surcharge",
    "trip_duration_min",
    "avg_speed_mph",
    "fare_per_mile",
    "tip_pct",
    "pickup_hour",
    "pickup_weekday",
]


def create_database():
    """Create a fresh database file and build all tables from schema.sql."""
    conn = sqlite3.connect(DB_PATH)
    # SQLite ignores foreign keys unless this is turned on for every connection
    conn.execute("PRAGMA foreign_keys = ON")
    conn.executescript(SCHEMA_PATH.read_text())
    return conn


def load_zones(conn):
    """Insert the 265 taxi zones from zones.csv into the zones tables."""
    df = pd.read_csv(OUTPUT_DIR / "zones.csv", keep_default_na=False)
    rows = list(df.itertuples(index=False, name=None))
    conn.executemany(
        "INSERT INTO zones (location_id, borough, zone, service_zone) VALUES (?, ?, ?, ?)",
        rows,
    )
    conn.commit()
    return len(rows)


def prepare_batch(df):
    """Fix one batch so it matches the trips table, and return it as rows."""
    # 1. rename: parquet name -> table name
    df = df.rename(columns={"payment_type": "payment_type_id"})

    # 2. timestamps -> text that SQLite can store and sort
    for col in ["pickup_datetime", "dropoff_datetime"]:
        df[col] = df[col].dt.strftime("%Y-%m-%d %H:%M:%S")

    # 3. keep only the table's columns, in the table's order
    df = df[TRIP_COLUMNS]

    # 4. empty values -> None, so SQLite stores NULL
    df = df.astype(object)
    df = df.where(df.notna(), None)

    return list(df.itertuples(index=False, name=None))


def load_trips(conn):
    """Read clean_trips.parquet in batches (step 1: just count the rows)."""
    pf = pq.ParquetFile(OUTPUT_DIR / "clean_trips.parquet")
    columns = ", ".join(TRIP_COLUMNS)
    placeholders = ", ".join(["?"] * len(TRIP_COLUMNS))
    sql = f"INSERT INTO trips ({columns}) VALUES ({placeholders})"


    total = 0
    batch_number = 0

    for batch in pf.iter_batches(batch_size=100_000):
        df = batch.to_pandas()
        batch_number = batch_number + 1
        rows = prepare_batch(df)
        conn.executemany(sql, rows)
        conn.commit()
        total = total + len(rows)
        print(f"batch {batch_number}: {len(rows)} rows inserted")

    return total


if __name__ == "__main__":
    conn = create_database()
    count = load_zones(conn)
    print("Zones loaded:", count)
    total = load_trips(conn)
    print("Trips inserted:", total)
    conn.close()

